var p = new Person("Alice");
Console.WriteLine(p.Greet());

record Person(string Name) { public string Greet() => "Hello, " + Name; }

var p = new Person();
p.SetName("Charlie");
Console.WriteLine(p.Name);

class Person { public string Name = "Bob"; public void SetName(string n) => Name = n; }

var c = new Counter(5);
Console.WriteLine($"{{{c.Increment().Value}}}");

record Counter(int Value) { public Counter Increment() => this with { Value = Value + 1 }; }

var b = new Builder();
Console.WriteLine(b.Add("Hello").Add("World").Build());

class Builder { public string Result = ""; public Builder Add(string s) { Result += s; return this; } public string Build() => Result; }

using System.Globalization;

var c = new Circle(5.0);
Console.WriteLine(c.Area().ToString("G17", CultureInfo.InvariantCulture));
Console.WriteLine(c.Perimeter().ToString("G17", CultureInfo.InvariantCulture));

record Circle(double Radius) { public double Area() => Math.PI * Radius * Radius; public double Perimeter() => 2 * Math.PI * Radius; }

Console.WriteLine(new MyInt(42).IsEven().ToString().ToLowerInvariant());

struct MyInt
{
    public int Value { get; }
    public MyInt(int value) => Value = value;
    public bool IsEven() => Value % 2 == 0;
}
